// Normalizes one Glean trigger delivery. The Trigger node emits only the parsed
// body, so `webhook-id` is unreachable and the key is doc_id plus event_time.
//
// Static data is absent in manual runs, so this fails OPEN: no store, no gate.
// Failing closed would drop real calls to prevent a duplicate.
const staticData = () => {
  try {
    return typeof $getWorkflowStaticData === 'function'
      ? $getWorkflowStaticData('global')
      : {};
  } catch {
    return {};
  }
};

const deliveries = $input.all();
if (deliveries.length > 1) {
  throw new Error(
    `One delivery carried ${deliveries.length} events. The nodes below resolve a single call, so a batch would attach one call's summary to another account. Nothing is written.`,
  );
}

const out = [];
for (const item of deliveries) {
  const event = item.json.body ?? item.json;

  if (event.datasource !== 'GONG') {
    throw new Error(
      `Expected a GONG delivery, got ${event.datasource}. The trigger is registered against the wrong preset.`,
    );
  }

  const callId = event.doc_id ?? '';
  const eventTime = event.event_time ?? '';
  if (!callId) {
    throw new Error(
      'Delivery carried no doc_id, so the call cannot be identified and nothing below can be deduplicated.',
    );
  }

  const deliveryId = eventTime ? `${callId}:${eventTime}` : callId;

  // Delivery is at-least-once and both writes below are irreversible. n8n saves
  // static data only on a successful execution, so a failed run leaves the key
  // unrecorded and its retry does the work.
  const state = staticData();
  const seen = Array.isArray(state.seenDeliveries) ? state.seenDeliveries : [];
  if (seen.includes(deliveryId)) {
    continue;
  }
  // Bounded: static data must stay small, and only a recent delivery is retried.
  state.seenDeliveries = [...seen, deliveryId].slice(-200);

  out.push({
    json: {
      deliveryId,
      triggerId: event.trigger_id ?? event.trigger_name ?? '',
      callId,
      title: (event.title ?? '').trim(),
      viewUrl: event.view_url ?? '',
      eventTime,
    },
  });
}
return out;

// Reads the Glean Chat HTTP response. Chat streams a plan as CONTENT before its
// tool work, so the answer is the CONTENT after the last UPDATE — taking every
// CONTENT glues the plan onto the summary.
const call = $('Extract call').first().json;
const response = $input.first().json ?? {};
const messages = response.messages ?? [];

// Chat signs off by offering to do more. A Salesforce Task and a customer Slack
// channel have nobody to answer that, so strip it.
const withoutSignOff = (value) => {
  const offer = /^(?:would you like|should i|do you want|let me know|i can also|shall i)\b/iu;
  return value
    .split(/\n\s*(?:-{3,}|\*{3,})\s*\n/u)
    .filter((block, index) => index === 0 || !offer.test(block.trim()))
    .join('\n\n')
    .replace(/\n[^\n]*\?\s*$/u, (line) => (offer.test(line.trim()) ? '' : line))
    .trim();
};

const lastUpdate = messages.map((m) => m.messageType).lastIndexOf('UPDATE');
const answerMessages = messages
  .slice(lastUpdate + 1)
  .filter((m) => m.messageType === 'CONTENT' && m.author === 'GLEAN_AI');

// Fragments within one message are a stream and concatenate directly; separate
// messages are separate paragraphs.
const text = withoutSignOff(
  answerMessages
    .map((m) => (m.fragments ?? []).map((f) => f.text ?? '').join(''))
    .join('\n\n'),
);

const citations = [
  ...new Map(
    answerMessages
      .flatMap((m) => m.fragments ?? [])
      .map((f) => f.citation?.sourceDocument)
      .filter((d) => d && d.title && d.url)
      .map((d) => [d.url, { title: d.title, url: d.url }]),
  ).values(),
];

// A 200 with no answer text is an unfinished run, not an empty call. Writing
// "no summary available" into Salesforce would record a transport failure as
// a fact about the customer conversation.
if (text === '') {
  throw new Error(
    `Glean Chat returned no answer text for call ${call.callId}. That is an unfinished run, not an empty call; retry rather than writing this to Salesforce.`,
  );
}

// The account the call was with, named by Chat rather than parsed out of the
// title. Real Gong titles are "people <> people : topic : Account" — the part
// before the separator is a participant, so reading the account from there
// picks a person's name. Free-form titles have no convention at all.
//
// Chat reads the call, so it can say who the customer is. It is not trusted to
// be right: Resolve account still requires exactly one exact Salesforce match,
// so a plausible-but-wrong name resolves to nothing and halts. The model
// proposes; deterministic matching disposes.
const accountLine = text.match(/^ACCOUNT:\s*(.+)$/mu);
const accountName = (accountLine?.[1] ?? '').trim();
const summary = text.replace(/^ACCOUNT:.*$/mu, '').trim();

return [
  {
    json: {
      call,
      summary,
      citations,
      accountName: /^unknown$/iu.test(accountName) ? '' : accountName,
    },
  },
];

// Requires exactly one matching Account, and halts otherwise: "Acme Corp" and
// "Acme Corporation" are different customers, so writing to the wrong one is a
// disclosure, not a degraded result. Ambiguity goes to a human, never to ranking.
//
// $input is the Salesforce rows; the call and summary come back by node name.
const normalize = (value) =>
  (value ?? '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\b(inc|llc|ltd|corp|corporation|co|plc|gmbh|sa|bv)\b/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

const { call, summary, citations, accountName } = $('Parse summary').first().json;
const accounts = $input.all().map((item) => item.json);

// The account is named by Glean Chat, not parsed from the title: Gong titles put
// participants before the separator, so splitting picks a person's name.

const rawName = accountName ?? '';
const wanted = normalize(rawName);

if (!wanted) {
  throw new Error(
    `Glean Chat could not name the customer for "${call.title}". Nothing is written; route this call to a human.`,
  );
}

const matches = accounts.filter((account) => normalize(account.Name) === wanted);

if (matches.length === 0) {
  throw new Error(
    `No Salesforce account matches "${rawName}". Nothing is written; create the account or route this call to a human.`,
  );
}
if (matches.length > 1) {
  throw new Error(
    `"${rawName}" matches ${matches.length} Salesforce accounts: ${matches
      .map((a) => `${a.Name} (${a.Id})`)
      .join(', ')}. Nothing is written; resolve the ambiguity by hand.`,
  );
}

return [{ json: { call, summary, citations, account: matches[0] } }];

// Routes to one central channel or a per-account map. Once a map exists, an
// unmapped account halts rather than falling back — quietly widening one
// customer's audience is the disclosure this node prevents.
// ─── paste your Slack channel id here ────────────────────────────────────
// One central channel is the simplest start; leave the map empty.
const SLACK_CHANNEL = ''; // e.g. 'C0123456789'
// Or route per account: Salesforce Account id -> Slack channel id.
const ACCOUNT_CHANNELS = {}; // e.g. { '001Ab00000XyZ12ABC': 'C0123456789' }
// ─────────────────────────────────────────────────────────────────────────
//
// n8n Variables are a paid feature, so these are plain constants and the
// workflow runs on any plan. If you do have Variables, GONG_SLACK_CHANNEL and
// GONG_ACCOUNT_CHANNELS override what is pasted above, so the same file works
// unedited across environments.
const vars = typeof $vars === 'undefined' ? {} : $vars;
const CHANNEL_BY_ACCOUNT_ID = vars.GONG_ACCOUNT_CHANNELS
  ? JSON.parse(vars.GONG_ACCOUNT_CHANNELS)
  : ACCOUNT_CHANNELS;
const CENTRAL_CHANNEL = vars.GONG_SLACK_CHANNEL || SLACK_CHANNEL;
const routesPerAccount = Object.keys(CHANNEL_BY_ACCOUNT_ID).length > 0;

const slackText = (value) =>
  String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

const { call, summary, citations, account } = $('Resolve account').first().json;
const channel = routesPerAccount
  ? CHANNEL_BY_ACCOUNT_ID[account.Id]
  : CENTRAL_CHANNEL;

if (!channel) {
  throw new Error(
    routesPerAccount
      ? `Account ${account.Name} (${account.Id}) has no entry in GONG_ACCOUNT_CHANNELS. Salesforce was updated; no Slack post was made. Add the mapping — this does not fall back to GONG_SLACK_CHANNEL, because per-account routing exists to keep audiences apart.`
      : `No Slack channel is configured. Paste a channel id into SLACK_CHANNEL at the top of this node, or fill ACCOUNT_CHANNELS to route per account. Salesforce was updated; no Slack post was made.`,
  );
}

const lines = [
  `*${slackText(account.Name)}* — new Gong call: <${call.viewUrl}|${slackText(call.title)}>`,
  '',
  slackText(summary),
];
if (citations.length > 0) {
  lines.push(
    '',
    `Sources: ${citations.map((c) => `<${c.url}|${slackText(c.title)}>`).join(' · ')}`,
  );
}

return [{ json: { call, account, channel, text: lines.join('\n') } }];
